fetch bizevents, from:-30d
| filter event.type == "com.easytrade.account"
| summarize takeLast(packageId), by:{accountId}
| fieldsRename tier = `takeLast(packageId)`
| summarize accounts = count(), by:{tier}
| sort tier asc

fetch bizevents, from:-7d
| filter in(event.type, {"com.easytrade.long-buy","com.easytrade.long-sell","com.easytrade.quick-buy","com.easytrade.quick-sell"})
| fieldsAdd notional = amount * price
| join [
    fetch bizevents, from:-7d
    | filter event.type == "com.easytrade.account"
    | summarize tier = takeLast(packageId), by:{accountId}
  ], on:{accountId}
| summarize volume = round(sum(notional)), trades = count(), traders = countDistinct(accountId), by:{tier = right.tier}
| fieldsAdd avg_volume_per_trader = round(volume / traders)
| sort tier asc
